  return x.rowIndex === formItem.index;
}).rowValues['VacationType'];

window.checkDates();

var url = `/api/functions/NNCheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${endDate}&employeeId=${initiatorId}&vacationTypeId=${vacationTypeId}`
