facilityFormItem.onClickEventHandler:
          
  var initiatorId = functions.getValues().PerformerId;
  var vacationTable = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
  var vacationPeriods = [];
  
  if (vacationTable && vacationTable.length > 0) {
    vacationTable.forEach(function(row) {
      vacationPeriods.push({
        StartDate: row.rowValues.BeginDate,
        EndDate: row.rowValues.EndDate
      });
    });
  }
  
  if (!initiatorId || vacationPeriods.length === 0) {
    ESS.toasts.showToast(ESS.L('@HRPROVACATIONS.FACILITIES_NN_SUBSTITUTION_SETUP_ERROR_MISSING_DATA'), 'warning', true);
    return;
  }
  
  functions.setIsItemHidden('ShowSubstitutesButton', false);
  functions.setIsItemHidden('SubstitutionsInfoBlock', true);
  
  window.prepareSubstitutionParameters();
  
  var substituteIdsString = functions.getValues().SubstituteIdsString;
  var systemIdsString = functions.getValues().SystemIdsString;
  var startDatesString = functions.getValues().StartDatesString;
  var endDatesString = functions.getValues().EndDatesString;
  
  ESS.actions.facilityActions.runFacility(
    {
      id: '2a5f2cfc-8646-4bb8-920c-a985b15da804' 
    },
    {
      parameters: {
        InitiatorId: initiatorId,
        VacationPeriodsJson: JSON.stringify(vacationPeriods),
        SubstituteIdsString: substituteIdsString,
        SystemIdsString: systemIdsString,
        StartDatesString: startDatesString,
        EndDatesString: endDatesString
      }
    }
  );

facility.openingEventHandler:
    var assignmentId = functions.getValues().AssignmentId; 
    ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
    .then(function (employee){
      if (employee.positions.length == 1) {
        functions.setIsItemHidden('PerformerInfo', true);
      }
    });
    ESS.network.sendRequest(`/api/functions/GetCurrentVacationInfoForShift?assignmentId=${assignmentId}`)
    .then(function (vacationInfo) {
      functions.setDataSource('VacationType', `/api/functions/GetVacationTypesForShift?noticeId=${vacationInfo.NoticeId}`);
      functions.setValue('NoticeId', vacationInfo.NoticeId);
      functions.setValue('VacationPeriod', vacationInfo.VacationPeriod);
      functions.setValue('BeginDateOld', vacationInfo.BeginDate);
      functions.setValue('DurationOld', vacationInfo.Duration);
      functions.setValue('EndDateOld', vacationInfo.EndDate);
      functions.setValue('PerformerInfo', vacationInfo.PerformerInfo);
      functions.setValue('VacationsOld', JSON.stringify(vacationInfo.Vacations));

      var initiatorId = functions.getValues().PerformerId;
      ESS.network.sendRequest(`/api/functions/GetVacationStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=true`)
      .then(function (VacationStatementData) {
        var templateId = VacationStatementData.TemplateId;
        var docKindId = VacationStatementData.DocumentKindId;
        functions.setValue('TemplateId', templateId);
        functions.setValue('DocumentKindId', docKindId);
        functions.setValue('IsFromEssAccount', true);
      });
      resolve();
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message, 'danger', false);
      reject();
    });

facility.openedEventHandler:
    
      window.setEndDate = function (rowIndex) {
        var initiatorId = functions.getValues().PerformerId;
        var vacationTypeId = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'].find(function (x) {
          return x.rowIndex === rowIndex;
        }).rowValues['VacationType'];
        var beginDateValue = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'].find(function (x) {
          return x.rowIndex === rowIndex;
        }).rowValues['BeginDate'];
        var durationValue = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'].find(function (x) {
          return x.rowIndex === rowIndex;
        }).rowValues['Duration'];
        
        if (durationValue != null && beginDateValue != null) {
          ESS.network.sendRequest(`/api/functions/NNGetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationTypeId=${vacationTypeId}`)
          .then(function (newEndDateValue) {
            functions.setValue('VacationType&BeginDate&Duration&EndDateGrid', newEndDateValue, rowIndex, 'EndDate');
          });
        };
      }

      window.getDurationOldByType = function (vacationTypeId) {
        var durationOld = 0;
        var vacations = JSON.parse(functions.getValues().VacationsOld);
        vacations.forEach(row => {
         if (row.VacationTypeId == vacationTypeId) {
            durationOld += +row.Duration;
          };
        });
        return durationOld;
      }

      window.getDurationByType = function (vacationTypeId) {
        var duration = 0;
        var rows = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
        rows.forEach(row => {
          if (row.rowValues.Duration != null && row.rowValues.VacationType == vacationTypeId) {
            duration += +row.rowValues.Duration;
          };
        });
        return duration;
      }

      window.checkDuration = function () {
        var tableName = 'VacationType&BeginDate&Duration&EndDateGrid';
        var rows = functions.getValues()[tableName];
        rows.forEach(row => {
          if (row.rowValues.Duration != null && row.rowValues.VacationType != null) {
            var vacationTypeId = row.rowValues.VacationType;
            var durationOld = window.getDurationOldByType(vacationTypeId);
            var duration = window.getDurationByType(vacationTypeId);
            functions.removeError(window[`errorDuration${vacationTypeId}`]);
            functions.removeError(window[`errorDuration${row.rowIndex}`]);
            if (duration > durationOld) {
              window[`errorDuration${vacationTypeId}`] = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_SHIFTANNUALVACATIONFROMCONFIRMATIONASSIGNMENT_DURATION_ERROR'), undefined, ESS.enums.FormErrorType.UNSPECIFIED, tableName, row.rowIndex, 'Duration');
              window[`errorDuration${row.rowIndex}`] = window[`errorDuration${vacationTypeId}`];
            }
          }
        });
      }

      window.checkDates = function () {
        var tableName = 'VacationType&BeginDate&Duration&EndDateGrid';
        var rows = functions.getValues()[tableName];
        rows.forEach(checkRow => {
          var currentBeginDate = new Date(checkRow.rowValues.BeginDate).getTime();
          var currentEndDate = new Date(checkRow.rowValues.EndDate).getTime();
          var currentIndex = checkRow.rowIndex;
          functions.removeError(window[`errorBeginDate${currentIndex}`]);
          functions.removeError(window[`errorEndDate${currentIndex}`]);
          rows.find(row => {
            if (currentIndex != row.rowIndex && row.rowValues.BeginDate != null && row.rowValues.EndDate != null) {
              var rowBeginDate = new Date(row.rowValues.BeginDate).getTime();
              var rowEndDate = new Date(row.rowValues.EndDate).getTime();
              var isError = false;
              if (currentBeginDate >= rowBeginDate && currentBeginDate <= rowEndDate) {
                window[`errorBeginDate${currentIndex}`] = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_SHIFTANNUALVACATIONFROMCONFIRMATIONASSIGNMENT_BEGINDATE_ERROR'), undefined, ESS.enums.FormErrorType.FORM_VALIDATION, tableName, currentIndex, 'BeginDate');
                isError = true;
              }
              if ((currentEndDate >= rowBeginDate && currentEndDate <= rowEndDate) || (currentBeginDate < rowEndDate && currentEndDate > rowEndDate)) {
                window[`errorEndDate${currentIndex}`] = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_SHIFTANNUALVACATIONFROMCONFIRMATIONASSIGNMENT_BEGINDATE_ERROR'), undefined, ESS.enums.FormErrorType.FORM_VALIDATION, tableName, currentIndex, 'EndDate');
                isError = true;
              }
              if (isError) {
                return true;
              }
            }
          });
        });
      }
      
      window.getSubstitutionDataFromStorage = function() {
        try {
          var storedData = localStorage.getItem('NNSubstitutionSetup_Data');
          
          if (!storedData || storedData === '' || storedData === 'null') {
            console.log('[getSubstitutionDataFromStorage] No data in localStorage');
            return null;
          }
          
          var data = JSON.parse(storedData);
          
          if (!data.SubstituteIdsString || data.SubstituteIdsString === '') {
            console.log('[getSubstitutionDataFromStorage] No substitute IDs');
            return null;
          }
          
          var result = {
            substituteIds: data.SubstituteIdsString.split(';').filter(function(id) { return id && id !== ''; }),
            substituteNames: data.SubstituteNamesString ? data.SubstituteNamesString.split(';') : [],
            systemIds: data.SystemIdsString.split(';').filter(function(id) { return id && id !== ''; }),
            systemNames: data.SystemNamesString ? data.SystemNamesString.split(';') : [],
            startDates: data.StartDatesString.split(';').filter(function(date) { return date && date !== ''; }),
            endDates: data.EndDatesString.split(';').filter(function(date) { return date && date !== ''; })
          };
          
          console.log('[getSubstitutionDataFromStorage] Data loaded:', result.substituteIds.length, 'substitutes');
          return result;
        }
        catch (e) {
          console.error('[getSubstitutionDataFromStorage] Parse error:', e);
          return null;
        }
      };

      window.showSubstitutionInfo = function() {
        var data = window.getSubstitutionDataFromStorage();
        
        if (!data || data.substituteIds.length === 0) {
          console.log('[showSubstitutionInfo] No data to display');
          functions.setIsItemHidden('SubstitutionsInfoBlock', true);
          functions.setIsItemHidden('ShowSubstitutesButton', true);
          functions.setValue('SubstitutionsInfo', '');
          return false;
        }
        
        var infoText = ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_HEADER')) + '<br/><br/>';
        
        for (var i = 0; i < data.substituteIds.length; i++) {
          var startDate = data.startDates[i] ? new Date(data.startDates[i]).toLocaleDateString('ru-RU') : '?';
          var endDate = data.endDates[i] ? new Date(data.endDates[i]).toLocaleDateString('ru-RU') : '?';
          var subName = data.substituteNames[i];
          var sysName = data.systemNames[i];
          
          infoText += ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_ITEM_TEMPLATE'),(i + 1), subName, sysName , startDate, endDate) + '<br/>';
        }
        
        functions.setValue('SubstitutionsInfo', infoText);
        functions.setIsItemHidden('SubstitutionsInfoBlock', false);
        functions.setIsItemHidden('ShowSubstitutesButton', false);
        
        console.log('[showSubstitutionInfo] Info displayed');
        return true;
      };

      window.prepareSubstitutionParameters = function() {
        var data = window.getSubstitutionDataFromStorage();
        
        if (!data || data.substituteIds.length === 0) {
          console.log('[prepareSubstitutionParameters] No data to prepare');
          
          functions.setValue('SubstituteIdsString', '');
          functions.setValue('SystemIdsString', '');
          functions.setValue('StartDatesString', '');
          functions.setValue('EndDatesString', '');
          
          return false;
        }
        
        functions.setValue('SubstituteIdsString', data.substituteIds.join(';'));
        functions.setValue('SystemIdsString', data.systemIds.join(';'));
        functions.setValue('StartDatesString', data.startDates.join(';'));
        functions.setValue('EndDatesString', data.endDates.join(';'));
        
        console.log('[prepareSubstitutionParameters] Parameters set:', data.substituteIds.length, 'substitutes');
        return true;
      };

facility.beforeSubmitEventHandler:
    window.prepareSubstitutionParameters();
    
    var initiatorId = functions.getValues().PerformerId;
    var noticeId = functions.getValues().NoticeId;
    var assignmentId = functions.getValues().AssignmentId;
    var documentKindId = functions.getValues().DocumentKindId;
    var oldDateStart = functions.getValues().BeginDateOld;
    var oldDateEnd = functions.getValues().EndDateOld;
    var durationOld = functions.getValues().DurationOld;
    var tableName = 'VacationType&BeginDate&Duration&EndDateGrid'; 
    var rows = functions.getValues()[tableName];
    var vacationTypeIdsArray = [];
    var vacationReasonIdsArray = [];
    var beginDateArray = [];
    var endDateArray = [];
    var durationArray = [];
    var duration = 0;
    rows.forEach(row => {
      duration += +row.rowValues.Duration;
      if (row.rowValues.BeginDate != null && row.rowValues.EndDate) {
        vacationTypeIdsArray.push(row.rowValues.VacationType);
        var beginDate = row.rowValues.BeginDate;
        beginDateArray.push(beginDate);
        var endDate = row.rowValues.EndDate;
        endDateArray.push(endDate);
        durationArray.push(row.rowValues.Duration);
      };
    });

    var vacationsOld = JSON.parse(functions.getValues().VacationsOld);
    var formattedVacationsOld = JSON.stringify(vacationsOld.map(item => {
      return {
        DateStart: item.BeginDate,
        DateEnd: item.EndDate,
        VacationTypeId: item.VacationTypeId,
        DaysCount: item.Duration,
      };
    }));
    functions.setValue('FormattedVacationsOld', formattedVacationsOld);
    
    var vacationType = 'Planned';
    var beginDates = rows.map(x => Date.parse(x.rowValues.BeginDate));
    var newStart = new Date(Math.min(...beginDates)).toLocaleDateString('en-CA');
    var oldStart = new Date(oldDateStart).toLocaleDateString('en-CA');
    ESS.network.sendRequest(`/api/functions/GetVacationApprovalDate?employeeId=${initiatorId}&documentKindId=${documentKindId}&vacationType=${vacationType}&paymentCompleted=false&isStatement=false&oldStart=${oldStart}&newStart=${newStart}`)
    .then(function (dateApproval) {
      var dateApprovalStr = new Date(dateApproval).toLocaleDateString('ru-RU');
      functions.setValue('ApprovalDate', dateApproval);
      
      ESS.scripts.HRProVacations.validateShiftVacationData({ functions, initiatorId, statementId: 0, noticeId, vacationTypeIdsArray, beginDateArray, endDateArray, durationArray, formattedVacationsOld, assignmentId })
      .then((success) => { 
        ESS.toasts.showToast(ESS.formatString(ESS.L('@HRPROVACATIONS.FACILITIES_NNSHIFTVACATIONBYSTATEMENT_APPROVALDATE_INFO'), dateApprovalStr), 'warning', false);
        var substitutionsInfo = functions.getValues().SubstitutionsInfo;
        if (!substitutionsInfo || substitutionsInfo === '' || substitutionsInfo === 'null') {
          resolve();
        } else {
          var vacationTable = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
          var vacationPeriods = [];
          if (vacationTable && vacationTable.length > 0) {
            vacationTable.forEach(function(row) {
              vacationPeriods.push({
                StartDate: row.rowValues.BeginDate,
                EndDate: row.rowValues.EndDate
              });
            });
          }
          
          ESS.scripts.HRProVacations.validateSubstitutionDates({ VacationPeriodsJson: JSON.stringify(vacationPeriods), StartDatesString: functions.getValues().StartDatesString || '', EndDatesString: functions.getValues().EndDatesString || '', IsCallingService: true })
          .then(function(substitutionResult) {
            if (substitutionResult && !substitutionResult.isValid) {
              if (substitutionResult.errors && substitutionResult.errors.length > 0) {
                ESS.toasts.showToast(substitutionResult.errors[0].message, 'danger', true);
                reject();
                return;
              }
            }
            resolve();
          })
          .catch(function (error) {
            reject();
          });
        }
      }, (error) => { reject() });
    })
    .catch(function (error) {
      reject();
    });
